// Assuming your Google Sheet has a 'Website' field
// This code assumes that the entries are returned in chronological order

let latestArticles;

// Get the last item in the $input array
const allItems = $input.all();
if (allItems.length > 0) {
    const latestItem = allItems[allItems.length - 1]; // Get the latest added entry
    latestArticles = latestItem.json.Articles; // Assuming 'Articles' is the field name
}

return {
    latestArticles: latestArticles
};
